<?php declare(strict_types=1);
require __DIR__.'/../src/Finance/Tax/TaxYearNotes.php';
use Kulturhus\Verein\TaxYearNotes;
$count=0;function check(bool $ok,string $label):void{global $count;if(!$ok)throw new RuntimeException($label);++$count;echo "PASS $label\n";}
function denied(callable $work,string $label):void{try{$work();}catch(DomainException){check(true,$label);return;}throw new RuntimeException($label);}
set_error_handler(static function(int $level,string $message,string $file,int $line):bool{if(!(error_reporting()&$level))return false;throw new ErrorException($message,0,$level,$file,$line);});
$year=(int)date('Y')-1;$normalize=static fn(array $r)=>TaxYearNotes::normalize([$year=>$r],$year,$year)[$year];
$unknown=$normalize([]);
check($unknown['receivables_cents']===null&&$unknown['liabilities_cents']===null&&$unknown['fixed_assets_book_value_cents']===null&&$unknown['other_assets_cents']===null,'missing monetary values are unknown, never zero');
foreach(['record_completeness','reserves_status','funds_use_status','corrections_status'] as $field)check($unknown[$field]==='unknown',$field.' defaults to unknown');
check(count(TaxYearNotes::normalize([],$year-2,$year))===3,'three selected years receive individual unknown worksheets');
check($normalize(['receivables'=>'0'])['receivables_cents']===0,'explicit zero remains known zero');
foreach(['1.234,56'=>123456,'1234.56'=>123456,'1.234'=>123400,'0,01'=>1,'1,2'=>120,'00001.05'=>105,' 12,00 '=>1200,'1.000.000.000,00'=>100000000000] as $input=>$expected)check($normalize(['receivables'=>(string)$input])['receivables_cents']===$expected,'exact cents '.$input);
check($normalize(['other_assets'=>'12,34'])['other_assets_cents']===1234,'other assets have their own exact amount');
foreach(['-1','+1','1e2','NaN','12,345','1.2345','1,234.56','1 234,56','1.000.000.000,01','9999999999999999999',true,12,1.23,[]] as $input)denied(fn()=>$normalize(['liabilities'=>$input]),'invalid or ambiguous amount rejected '.json_encode($input));
foreach([[1999,$year],[$year,$year-1],[$year-3,$year],[$year,(int)date('Y')+1]] as [$from,$to])denied(fn()=>TaxYearNotes::normalize([],$from,$to),'invalid report range rejected');
denied(fn()=>TaxYearNotes::normalize(['year'=>[]],$year,$year),'arbitrary year key rejected');
denied(fn()=>TaxYearNotes::normalize([$year=>'text'],$year,$year),'non-worksheet year rejected');
denied(fn()=>$normalize(['unexpected'=>'value']),'unknown top-level field rejected');
denied(fn()=>$normalize(['reserves'=>'text']),'non-list reserves rejected');
denied(fn()=>$normalize(['reserves'=>[1=>[]]]),'sparse row indexes rejected');
denied(fn()=>$normalize(['reserves'=>array_fill(0,11,[])]),'reserve maximum enforced');
denied(fn()=>$normalize(['corrections'=>array_fill(0,21,[])]),'correction maximum enforced');
denied(fn()=>$normalize(['valuation_note'=>"x\0y"]),'control characters rejected');
denied(fn()=>$normalize(['valuation_note'=>"\xFF"]),'invalid UTF-8 rejected');
denied(fn()=>$normalize(['record_completeness_note'=>str_repeat('ä',1001)]),'text bounded by UTF-8 bytes');
check($normalize(['record_completeness'=>'incomplete','record_completeness_note'=>" Unterlagen fehlen\r\nNoch prüfen "])['record_completeness_note']==="Unterlagen fehlen\nNoch prüfen",'review note trimmed without losing line breaks');
denied(fn()=>$normalize(['record_completeness'=>'approved']),'manual review cannot assert an official approval');
$reserve=['purpose'=>'Geplante Reparatur','reason'=>'Beschluss und Aufstellung','opening'=>'100,00','addition'=>'20,00','use'=>'30,00','closing'=>'90,00'];
$r=$normalize(['reserves_status'=>'listed','reserves'=>[$reserve]])['reserves'][0];
check($r['opening_cents']===10000&&$r['addition_cents']===2000&&$r['use_cents']===3000&&$r['closing_cents']===9000&&$r['calculation_status']==='balanced','reserve arithmetic uses exact cents');
denied(fn()=>$normalize(['reserves_status'=>'listed','reserves'=>[array_replace($reserve,['closing'=>'89,99'])]]),'mismatched reserve closing rejected');
$partial=$normalize(['reserves_status'=>'listed','reserves'=>[array_replace($reserve,['addition'=>''])]])['reserves'][0];
check($partial['addition_cents']===null&&$partial['calculation_status']==='unknown','partially unknown reserve never assumes a zero movement');
foreach(['purpose','reason'] as $field)denied(fn()=>$normalize(['reserves_status'=>'listed','reserves'=>[array_replace($reserve,[$field=>''])]]),'reserve '.$field.' required');
check($normalize(['reserves_status'=>'none'])['reserves_status']==='none','explicitly no reserves is distinct from unknown');
denied(fn()=>$normalize(['reserves_status'=>'none','reserves'=>[$reserve]]),'none cannot silently discard populated reserve');
denied(fn()=>$normalize(['reserves_status'=>'listed','reserves'=>[[]]]),'listed reserves require an actual entry');
$correction=['sphere'=>'4','direction'=>'add','amount'=>'42,05','reason'=>'Manuell geprüfte Überleitung laut Unterlage'];
$c=$normalize(['corrections_status'=>'listed','corrections'=>[$correction,array_replace($correction,['sphere'=>'3','direction'=>'subtract','amount'=>'2,05'])]])['corrections'];
check($c[0]['amount_cents']===4205&&$c[0]['sphere']==='4'&&$c[1]['direction']==='subtract','manual add/subtract retain amount, sphere and reason without tariff calculation');
foreach(['sphere'=>'9','direction'=>'automatic','amount'=>'','reason'=>''] as $field=>$value)denied(fn()=>$normalize(['corrections_status'=>'listed','corrections'=>[array_replace($correction,[$field=>$value])]]),'invalid correction '.$field.' rejected');
denied(fn()=>$normalize(['corrections_status'=>'unknown','corrections'=>[$correction]]),'populated correction cannot disappear behind unknown state');
check($normalize(['corrections_status'=>'none'])['corrections_status']==='none','explicit no corrections supported');
denied(fn()=>$normalize(['corrections_status'=>'listed','corrections'=>[]]),'listed corrections require an actual entry');
denied(fn()=>$normalize(['funds_use_status'=>'entered','funds_use_note'=>'']),'entered means an actual funds-use explanation');
denied(fn()=>$normalize(['funds_use_status'=>'unknown','funds_use_note'=>'Existing note']),'existing funds-use note is not silently discarded');
check($normalize(['funds_use_status'=>'entered','funds_use_note'=>'Tatsächliche Vereinsarbeit'])['funds_use_note']==='Tatsächliche Vereinsarbeit','manual funds-use explanation retained');
check(TaxYearNotes::normalize([$year-1=>[]],$year,$year)===[$year=>$unknown],'blank old worksheet can be ignored after range change');
denied(fn()=>TaxYearNotes::normalize([$year-1=>['receivables'=>'0']],$year,$year),'known zero outside selection is not silently discarded');
denied(fn()=>TaxYearNotes::normalize([$year-1=>['reserves_status'=>'none']],$year,$year),'explicit no-reserve declaration outside selection is not silently discarded');
// Render untrusted drafts through the actual view, including an out-of-range draft.
function e(mixed $value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$taxNotesFrom=$year;$taxNotesTo=$year;$taxNotesInput=[$year=>['valuation_note'=>'<script>alert(1)</script>','reserves_status'=>'listed','reserves'=>[$reserve]],$year-1=>['receivables'=>'0']];
ob_start();require __DIR__.'/../views/Finance/Tax/tax-year-notes.php';$html=ob_get_clean();
check(str_contains($html,'&lt;script&gt;alert(1)&lt;/script&gt;')&&!str_contains($html,'<script>alert(1)</script>'),'view escapes stored and posted text');
check(str_contains($html,'tax_year_notes['.$year.'][reserves][0][opening]'),'structured field names follow the agreed contract');
check(str_contains($html,'Angaben für '.($year-1).' entfernen'),'out-of-range draft remains visible and explicitly removable');
check(str_contains($html,'data-tax-notes-template="reserves"')&&str_contains($html,'data-tax-notes-template="corrections"'),'progressive lists have local add templates');
check(str_contains($html,'Unbekannte Beträge leer lassen')&&str_contains($html,'geprüfter Buchwert')&&str_contains($html,'Weiteres Vermögen ohne Bank'),'view explains unknown, book value and other assets');
echo "$count manual tax year notes checks passed; no database, network or mail\n";
